func (this *Bybit) ParseTransaction(transaction any, optionalArgs ...any) any {
	//
	// fetchWithdrawals
	//
	//     {
	//         "coin": "USDT",
	//         "chain": "TRX",
	//         "amount": "12.34",
	//         "txID": "de5ea0a2f2e59dc9a714837dd3ddc6d5e151b56ec5d786d351c4f52336f80d3c",
	//         "status": "success",
	//         "toAddress": "TQdmFKUoe1Lk2iwZuwRJEHJreTUBoN3BAw",
	//         "tag": "",
	//         "withdrawFee": "0.5",
	//         "createTime": "1665144183000",
	//         "updateTime": "1665144256000",
	//         "withdrawId": "8839035"
	//     }
	//
	// fetchDeposits
	//
	//     {
	//         "coin": "USDT",
	//         "chain": "TRX",
	//         "amount": "44",
	//         "txID": "0b038ea12fa1575e2d66693db3c346b700d4b28347afc39f80321cf089acc960",
	//         "status": "3",
	//         "toAddress": "TC6NCAC5WSVCCiaD3kWZXyW91ZKKhLm53b",
	//         "tag": "",
	//         "depositFee": "",
	//         "successAt": "1665142507000",
	//         "confirmations": "100",
	//         "txIndex": "0",
	//         "blockHash": "0000000002ac3b1064aee94bca1bd0b58c4c09c65813b084b87a2063d961129e"
	//     }
	//
	// withdraw
	//
	//     {
	//         "id": "9377266"
	//     }
	//
	currency := GetArg(optionalArgs, 0, nil)
	_ = currency
	var currencyId any = this.SafeString(transaction, "coin")
	var code any = this.SafeCurrencyCode(currencyId, currency)
	var timestamp any = this.SafeInteger2(transaction, "createTime", "successAt")
	var updated any = this.SafeInteger(transaction, "updateTime")
	var status any = this.ParseTransactionStatus(this.SafeString(transaction, "status"))
	var feeCost any = this.SafeNumber2(transaction, "depositFee", "withdrawFee")
	var typeVar any = Ternary(IsTrue((InOp(transaction, "depositFee"))), "deposit", "withdrawal")
	var fee any = nil
	if IsTrue(!IsEqual(feeCost, nil)) {
		fee = map[string]any{
			"cost":     feeCost,
			"currency": code,
		}
	}
	var toAddress any = this.SafeString(transaction, "toAddress")
	return map[string]any{
		"info":        transaction,
		"id":          this.SafeString2(transaction, "id", "withdrawId"),
		"txid":        this.SafeString(transaction, "txID"),
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"network":     this.NetworkIdToCode(this.SafeString(transaction, "chain"), code),
		"address":     nil,
		"addressTo":   toAddress,
		"addressFrom": nil,
		"tag":         this.SafeString(transaction, "tag"),
		"tagTo":       nil,
		"tagFrom":     nil,
		"type":        typeVar,
		"amount":      this.SafeNumber(transaction, "amount"),
		"currency":    code,
		"status":      status,
		"updated":     updated,
		"fee":         fee,
		"internal":    nil,
		"comment":     nil,
	}
}

