	//         "type": "TRADE",
	//         "feeRate": "0.0006",
	//         "size": "12",
	//         "qty": "12",
	//         "cashBalance": "5086.58101322",
	//         "currency": "USDT",
	//         "category": "linear",
	//         "tradePrice": "0.3615",
	//         "tradeId": "8569c10f-5061-5891-81c4-a54929847eb3"
	//     }
	//
	currency := GetArg(optionalArgs, 0, nil)
	_ = currency
	var currencyId any = this.SafeString2(item, "coin", "currency")
